package com.thangit.boardinghouse.service;

import com.thangit.boardinghouse.common.exception.AuthException;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import com.thangit.boardinghouse.security.PropertyAuthorization;
import com.thangit.boardinghouse.security.SecurityAudit;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.constraints.*;
import java.time.*;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** One inbox (notifications), one durable delivery queue. Never mutates financial/lifecycle sources. */
@Service
@Transactional(readOnly=true)
public class CommunicationService {
 public static String canonicalEvent(String event){return "INVOICE_DUE_SOON".equals(event)?"INVOICE_BEFORE_DUE":event;}
 public static final ZoneId ZONE=ZoneId.of("Asia/Ho_Chi_Minh");
 public static final Set<String> EVENTS=Set.of("CONTRACT_CREATED","CONTRACT_CONFIRMED","INVOICE_ISSUED","PAYMENT_OPEN","INVOICE_BEFORE_DUE","INVOICE_DUE","INVOICE_OVERDUE","PAYMENT_CONFIRMED","PAYMENT_FAILED","CONTRACT_EXPIRY","CHECKIN","CHECKOUT","MAINTENANCE_CREATED","MAINTENANCE_ASSIGNED","MAINTENANCE_DUE","MAINTENANCE_URGENT","MAINTENANCE_COMPLETED","DEPOSIT_REFUNDED");
 public static final Set<String> CATEGORIES=Set.of("ANNOUNCEMENT","INVOICE","PAYMENT","CONTRACT","MAINTENANCE","CHECKOUT","TASK","SYSTEM","UTILITY","EMERGENCY");
 public static final Set<String> CHANNELS=Set.of("IN_APP","EMAIL","SMS","ZALO","WEB_PUSH");
 final JdbcClient db;final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
 public CommunicationService(JdbcClient db){this.db=db;}
 public static LocalDateTime now(){return com.thangit.boardinghouse.service.BusinessTime.now(ZONE);}
 public static long number(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
 public static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 public static AuthException bad(String m){return new AuthException(HttpStatus.BAD_REQUEST,"COMMUNICATION_INVALID",m);}
 static AuthException denied(){return new AuthException(HttpStatus.FORBIDDEN,"COMMUNICATION_DENIED","Không có quyền trong phạm vi này.");}
 static AuthException conflict(){return new AuthException(HttpStatus.CONFLICT,"COMMUNICATION_CHANGED","Dữ liệu đã thay đổi; xem trước/tải lại trước khi xác nhận.");}
 static void text(String s,int max){if(s==null||s.isBlank()||s.length()>max||s.matches("(?is).*<[^>]*>.*"))throw bad("Nội dung văn bản không hợp lệ; không nhập HTML/script.");}
 String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw bad("Không thể lưu nội dung.");}}
 public List<Long> properties(AuthenticatedUser p){if(p==null)throw denied();String condition=switch(p.activeRole()){
  case OWNER->"p.owner_id=:actor";
  case MANAGER->"EXISTS(SELECT 1 FROM property_managers a WHERE a.property_id=p.id AND a.manager_id=:actor)";
  case ACCOUNTANT->"EXISTS(SELECT 1 FROM accountant_property_assignments a JOIN accountant_profiles ap ON ap.user_id=a.accountant_id WHERE a.property_id=p.id AND a.accountant_id=:actor)";
  case TECHNICIAN->"EXISTS(SELECT 1 FROM technician_property_assignments ta WHERE ta.property_id=p.id AND ta.technician_id=:actor AND ta.revoked_at IS NULL) OR EXISTS(SELECT 1 FROM maintenance_requests m WHERE m.property_id=p.id AND m.assigned_to=:actor) OR EXISTS(SELECT 1 FROM operational_tasks t WHERE t.property_id=p.id AND t.assignee_id=:actor)";
  case TENANT->"EXISTS(SELECT 1 FROM contracts c JOIN rooms r ON r.id=c.room_id WHERE r.property_id=p.id AND c.tenant_id=:actor)";
 };return db.sql("SELECT p.id FROM properties p WHERE "+condition+" ORDER BY p.id").param("actor",p.id()).query(Long.class).list();}
 List<Long> safe(List<Long> ids){return ids.isEmpty()?List.of(-1L):ids;}
 void property(AuthenticatedUser p,long id){if(!properties(p).contains(id))throw denied();}
 void manage(AuthenticatedUser p,long id,boolean finance){property(p,id);if(!Set.of(RoleCode.OWNER,RoleCode.MANAGER,RoleCode.ACCOUNTANT).contains(p.activeRole()))throw denied();if(p.activeRole()==RoleCode.ACCOUNTANT&&!finance)throw denied();if(p.activeRole()==RoleCode.MANAGER)new PropertyAuthorization(db,new SecurityAudit(db)).require(p,id,finance?PropertyAuthorization.Capability.FINANCE_WRITE:PropertyAuthorization.Capability.CONTRACT_APPROVE);if(p.activeRole()==RoleCode.ACCOUNTANT&&db.sql("SELECT can_record_payment FROM accountant_profiles WHERE user_id=:id").param("id",p.id()).query(Boolean.class).optional().orElse(false)==false)throw denied();}
 boolean financeCategory(String c){return Set.of("INVOICE","PAYMENT").contains(c);}
 public List<Map<String,Object>> recipients(long property){return db.sql("""
 SELECT DISTINCT u.id,u.full_name name,'TENANT' recipient_role,c.room_id FROM users u JOIN contracts c ON c.tenant_id=u.id JOIN rooms r ON r.id=c.room_id WHERE r.property_id=:id AND c.status IN ('ACTIVE','EXPIRING','EXPIRED','TERMINATION_REQUESTED','SETTLING') AND u.status='ACTIVE'
 UNION SELECT u.id,u.full_name,'OWNER',NULL FROM users u JOIN properties p ON p.owner_id=u.id WHERE p.id=:id AND u.status='ACTIVE'
 UNION SELECT u.id,u.full_name,'MANAGER',NULL FROM users u JOIN property_managers a ON a.manager_id=u.id WHERE a.property_id=:id AND u.status='ACTIVE' AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles role ON role.id=ur.role_id WHERE ur.user_id=u.id AND role.code='MANAGER')
 UNION SELECT u.id,u.full_name,'ACCOUNTANT',NULL FROM users u JOIN accountant_property_assignments a ON a.accountant_id=u.id WHERE a.property_id=:id AND u.status='ACTIVE' AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles role ON role.id=ur.role_id WHERE ur.user_id=u.id AND role.code='ACCOUNTANT')
 UNION SELECT u.id,u.full_name,'TECHNICIAN',NULL FROM users u JOIN technician_property_assignments a ON a.technician_id=u.id WHERE a.property_id=:id AND a.revoked_at IS NULL AND u.status='ACTIVE' AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles rl ON rl.id=ur.role_id WHERE ur.user_id=u.id AND rl.code='TECHNICIAN')
 UNION SELECT u.id,u.full_name,'TECHNICIAN',NULL FROM users u JOIN maintenance_requests m ON m.assigned_to=u.id WHERE m.property_id=:id AND u.status='ACTIVE' AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles role ON role.id=ur.role_id WHERE ur.user_id=u.id AND role.code='TECHNICIAN')
 UNION SELECT u.id,u.full_name,'TECHNICIAN',NULL FROM users u JOIN operational_tasks t ON t.assignee_id=u.id WHERE t.property_id=:id AND u.status='ACTIVE' AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles role ON role.id=ur.role_id WHERE ur.user_id=u.id AND role.code='TECHNICIAN')
 ORDER BY name,id
 """).param("id",property).query().listOfRows();}
 boolean canManage(AuthenticatedUser p,long property,boolean finance){try{manage(p,property,finance);return true;}catch(AuthException denied){return false;}}
 public Map<String,Object> options(AuthenticatedUser p){var ids=properties(p);var permissions=ids.stream().map(id->Map.of("propertyId",id,"canManage",canManage(p,id,false),"canSend",canManage(p,id,false)||canManage(p,id,true))).toList();return Map.of("permissions",permissions,"properties",db.sql("SELECT p.id,p.name,op.organization_id organizationId,o.name organizationName FROM properties p LEFT JOIN organization_property_relationships op ON op.property_id=p.id AND op.ended_at IS NULL LEFT JOIN organizations o ON o.id=op.organization_id WHERE p.id IN (:ids) ORDER BY p.name").param("ids",safe(ids)).query().listOfRows(),"channels",List.of(Map.of("code","IN_APP","available",true,"status","AVAILABLE"),Map.of("code","EMAIL","available",false,"status","NOT_CONFIGURED"),Map.of("code","SMS","available",false,"status","NOT_CONFIGURED"),Map.of("code","ZALO","available",false,"status","NOT_CONFIGURED")),"events",EVENTS.stream().sorted().toList(),"canManage",permissions.stream().anyMatch(v->Boolean.TRUE.equals(v.get("canManage"))),"canSend",permissions.stream().anyMatch(v->Boolean.TRUE.equals(v.get("canSend"))));}
 public Object audience(AuthenticatedUser p,long property){manage(p,property,p.activeRole()==RoleCode.ACCOUNTANT);return Map.of("recipients",recipients(property).stream().filter(r->p.activeRole()!=RoleCode.ACCOUNTANT||"TENANT".equals(r.get("recipient_role"))).toList(),"rooms",db.sql("SELECT id,code FROM rooms WHERE property_id=:id ORDER BY code").param("id",property).query().listOfRows());}
 public Map<String,Object> inbox(AuthenticatedUser p,Long property,String category,String read,LocalDate from,LocalDate to,String keyword,int page,int size){properties(p);page(page,size);var args=new HashMap<String,Object>();args.put("actor",p.id());String where=" WHERE n.user_id=:actor AND n.archived_at IS NULL";if(property!=null){property(p,property);where+=" AND n.property_id=:property";args.put("property",property);}if(category!=null&&!category.isBlank()){where+=" AND n.category=:category";args.put("category",category);}if("UNREAD".equals(read))where+=" AND n.read_at IS NULL";if("READ".equals(read))where+=" AND n.read_at IS NOT NULL";if(from!=null){where+=" AND n.created_at>=:from";args.put("from",from.atStartOfDay());}if(to!=null){if(from!=null&&to.isBefore(from))throw bad("Khoảng ngày không hợp lệ.");where+=" AND n.created_at<:to";args.put("to",to.plusDays(1).atStartOfDay());}if(keyword!=null&&!keyword.isBlank()){where+=" AND (n.title LIKE :keyword OR n.content LIKE :keyword)";args.put("keyword","%"+keyword.trim()+"%");}long count=db.sql("SELECT COUNT(*) FROM notifications n"+where).params(args).query(Long.class).single();args.put("limit",size);args.put("offset",(long)page*size);var rows=db.sql("SELECT n.id,n.title,n.content,n.category,n.severity,n.created_at,n.read_at,n.property_id,p.name property_name,n.reference_type,n.reference_id FROM notifications n LEFT JOIN properties p ON p.id=n.property_id"+where+" ORDER BY n.created_at DESC,n.id DESC LIMIT :limit OFFSET :offset").params(args).query().listOfRows();for(var r:rows)r.put("link",link(p.activeRole(),Objects.toString(r.get("reference_type"),""),r.get("reference_id")));return Map.of("rows",rows,"totalElements",count,"totalPages",(count+size-1)/size,"unreadCount",unread(p));}
 public long unread(AuthenticatedUser p){if(p==null)throw denied();return db.sql("SELECT COUNT(*) FROM notifications WHERE user_id=:id AND archived_at IS NULL AND read_at IS NULL").param("id",p.id()).query(Long.class).single();}
 @Transactional public void read(AuthenticatedUser p,Long id){if(p==null)throw denied();if(id!=null&&db.sql("SELECT COUNT(*) FROM notifications WHERE id=:id AND user_id=:actor").param("id",id).param("actor",p.id()).query(Long.class).single()!=1)throw denied();db.sql("UPDATE notifications SET read_at=COALESCE(read_at,:now),version=version+1 WHERE user_id=:actor AND archived_at IS NULL AND read_at IS NULL"+(id==null?"":" AND id=:id")).param("now",now()).param("actor",p.id()).params(id==null?Map.of():Map.of("id",id)).update();}
 public static String link(RoleCode role,String type,Object id){if(id==null)return "";String root=switch(role){case OWNER,MANAGER->"/admin";case ACCOUNTANT->"/accountant";case TENANT->"/tenant";case TECHNICIAN->"/technician";};return switch(type){case "INVOICE"->role==RoleCode.TECHNICIAN?"":root+"/invoices/"+id;case "CONTRACT"->role==RoleCode.TECHNICIAN?"":role==RoleCode.ACCOUNTANT?"/accountant/checkouts?contractId="+id:root+"/contracts/"+id;case "CHECKIN"->role==RoleCode.TENANT?"/tenant/contracts/"+id:role==RoleCode.OWNER||role==RoleCode.MANAGER?"/admin/rental-lifecycle?tab=checkin":"";case "CHECKOUT"->role==RoleCode.TENANT?"/tenant/contracts/"+id:role==RoleCode.TECHNICIAN?"":root+"/checkouts?contractId="+id;case "MAINTENANCE"->role==RoleCode.TENANT?"/tenant/maintenance/"+id:role==RoleCode.TECHNICIAN?"/technician/tasks/"+id:role==RoleCode.ACCOUNTANT?"/accountant/notifications":"/admin/maintenance/"+id;case "TASK"->(role==RoleCode.OWNER||role==RoleCode.MANAGER?"/admin/communications":root+"/notifications")+"?tab=calendar";default->"";};}
 static void page(int page,int size){if(page<0||size<1||size>100)throw bad("Phân trang không hợp lệ.");}
 public record Message(@Positive long propertyId,@NotBlank @Size(max=200) String title,@NotBlank @Size(max=5000) String body,@NotBlank String category,@NotBlank String audience,@NotNull @Size(max=500) List<@NotNull @Positive Long> recipientIds,@NotNull @Size(max=200) List<@NotNull @Positive Long> roomIds,@NotEmpty @Size(max=4) List<@NotBlank String> channels,@NotNull LocalDateTime scheduledAt,Long templateId){}
 public record Submit(@jakarta.validation.Valid @NotNull Message message,@NotBlank String previewHash,@NotBlank @Size(max=100) String key,boolean draft){}
 List<Map<String,Object>> selected(AuthenticatedUser p,Message m){manage(p,m.propertyId(),financeCategory(m.category()));text(m.title(),200);text(m.body(),5000);if(!CATEGORIES.contains(m.category())||!CHANNELS.containsAll(m.channels())||!Set.of("ALL_TENANTS","ROOMS","SELECTED","MANAGER","ACCOUNTANT","TECHNICIAN").contains(m.audience()))throw bad("Nhóm, loại hoặc kênh không hợp lệ.");if(p.activeRole()==RoleCode.ACCOUNTANT&&!Set.of("ALL_TENANTS","ROOMS","SELECTED").contains(m.audience()))throw denied();if(m.scheduledAt().isAfter(now().plusYears(1)))throw bad("Lịch gửi tối đa một năm.");var all=recipients(m.propertyId());var result=all.stream().filter(r->switch(m.audience()){case "ALL_TENANTS"->"TENANT".equals(r.get("recipient_role"));case "ROOMS"->"TENANT".equals(r.get("recipient_role"))&&r.get("room_id")!=null&&m.roomIds().contains(number(r,"room_id"));case "SELECTED"->m.recipientIds().contains(number(r,"id"));default->m.audience().equals(r.get("recipient_role"));}).filter(r->(!financeCategory(m.category())&&p.activeRole()!=RoleCode.ACCOUNTANT)||"TENANT".equals(r.get("recipient_role"))).collect(java.util.stream.Collectors.toMap(r->number(r,"id"),r->r,(a,b)->a,TreeMap::new)).values().stream().toList();if(result.isEmpty()||result.size()>500)throw bad("Chọn từ 1 đến 500 người nhận trong phạm vi.");if("SELECTED".equals(m.audience())&&!new HashSet<>(result.stream().map(r->number(r,"id")).toList()).equals(new HashSet<>(m.recipientIds())))throw denied();if("ROOMS".equals(m.audience())&&db.sql("SELECT COUNT(*) FROM rooms WHERE property_id=:property AND id IN (:ids)").param("property",m.propertyId()).param("ids",m.roomIds().isEmpty()?List.of(-1L):m.roomIds()).query(Long.class).single()!=m.roomIds().stream().distinct().count())throw denied();if(m.templateId()!=null){var t=template(p,m.templateId());if(number(t,"property_id")!=m.propertyId()||!Boolean.TRUE.equals(t.get("enabled")))throw denied();}return result;}
 String previewHash(Message m,List<Map<String,Object>> audience){return hash(encode(m)+"|"+audience.stream().map(r->number(r,"id")).sorted().toList());}
 public Map<String,Object> preview(AuthenticatedUser p,Message m){var rows=selected(p,m);var rendered=rows.stream().limit(10).map(r->Map.of("recipientId",number(r,"id"),"title",renderMessage(m,r,m.title(),200),"body",renderMessage(m,r,m.body(),5000))).toList();return Map.of("rendered",rendered,"recipients",rows,"recipientCount",rows.size(),"deliveryCount",rows.size()*new HashSet<>(m.channels()).size(),"previewHash",previewHash(m,rows),"channels",m.channels(),"externalConfigured",false);}
 @Transactional public long submit(AuthenticatedUser p,Submit s){var rows=selected(p,s.message());String h=previewHash(s.message(),rows);String intentHash=hash(h+"|draft="+s.draft());if(!h.equals(s.previewHash()))throw conflict();db.sql("SELECT id FROM users WHERE id=:id FOR UPDATE").param("id",p.id()).query(Long.class).single();var prior=db.sql("SELECT id,payload_hash FROM communication_campaigns WHERE created_by=:actor AND request_key=:key FOR UPDATE").param("actor",p.id()).param("key",s.key()).query().listOfRows();if(!prior.isEmpty()){if(!intentHash.equals(prior.getFirst().get("payload_hash")))throw conflict();return number(prior.getFirst(),"id");}var m=s.message();long id=insert("INSERT INTO communication_campaigns(property_id,created_by,actor_role,title,body,category,payload,payload_hash,request_key,status,scheduled_at) VALUES(:property,:actor,:role,:title,:body,:category,:payload,:hash,:key,:status,:at)",Map.ofEntries(Map.entry("property",m.propertyId()),Map.entry("actor",p.id()),Map.entry("role",p.activeRole().name()),Map.entry("title",m.title()),Map.entry("body",m.body()),Map.entry("category",m.category()),Map.entry("payload",encode(m)),Map.entry("hash",intentHash),Map.entry("key",s.key()),Map.entry("status",s.draft()?"DRAFT":m.scheduledAt().isAfter(now())?"SCHEDULED":"QUEUED"),Map.entry("at",m.scheduledAt())));if(!s.draft())enqueue(id,m,rows);audit(p,m.propertyId(),"CAMPAIGN",id,s.draft()?"DRAFT_CREATED":"QUEUED","recipients="+rows.size()+"; channels="+new HashSet<>(m.channels()));return id;}
 long insert(String sql,Map<String,?> params){var key=new GeneratedKeyHolder();db.sql(sql).params(params).update(key,"id");return key.getKey().longValue();}
 void enqueue(long campaign,Message m,List<Map<String,Object>> rows){for(var r:rows)for(String channel:new TreeSet<>(m.channels()))db.sql("INSERT INTO communication_deliveries(campaign_id,property_id,recipient_id,channel,category,title,body,business_key,status,scheduled_at,next_attempt_at) VALUES(:campaign,:property,:recipient,:channel,:category,:title,:body,:key,:status,:at,:at)").param("campaign",campaign).param("property",m.propertyId()).param("recipient",number(r,"id")).param("channel",channel).param("category",m.category()).param("title",renderMessage(m,r,m.title(),200)).param("body",renderMessage(m,r,m.body(),5000)).param("key",hash("MANUAL|"+campaign+"|"+r.get("id")+"|"+channel)).param("status",m.scheduledAt().isAfter(now())?"SCHEDULED":"QUEUED").param("at",m.scheduledAt()).update();}
 String renderMessage(Message m,Map<String,Object> recipient,String value,int max){String body=render(value,Map.of("property",db.sql("SELECT name FROM properties WHERE id=:id").param("id",m.propertyId()).query(String.class).single(),"name",recipient.get("name"),"date",m.scheduledAt().toLocalDate().toString()));text(body,max);return body;}
 public record Version(@Min(0) long version){}
 @Transactional public void campaignAction(AuthenticatedUser p,long id,String action,Version v){var c=db.sql("SELECT * FROM communication_campaigns WHERE id=:id FOR UPDATE").param("id",id).query().singleRow();manage(p,number(c,"property_id"),financeCategory(c.get("category").toString()));if(number(c,"version")!=v.version())throw conflict();if("queue".equals(action)){if(!"DRAFT".equals(c.get("status")))throw conflict();Message m;try{m=json.readValue(c.get("payload").toString(),Message.class);}catch(Exception e){throw bad("Bản nháp không hợp lệ.");}var rows=selected(p,m);if(!hash(previewHash(m,rows)+"|draft=true").equals(c.get("payload_hash")))throw conflict();enqueue(id,m,rows);db.sql("UPDATE communication_campaigns SET status='QUEUED',version=version+1 WHERE id=:id").param("id",id).update();}else if("cancel".equals(action)){if("CANCELLED".equals(c.get("status")))throw conflict();db.sql("UPDATE communication_deliveries SET status='CANCELLED',result_code='MANUAL_CANCEL',finished_at=:now WHERE campaign_id=:id AND status IN ('SCHEDULED','QUEUED','FAILED')").param("now",now()).param("id",id).update();db.sql("UPDATE communication_campaigns SET status='CANCELLED',version=version+1 WHERE id=:id").param("id",id).update();}else throw bad("Thao tác không hợp lệ.");audit(p,number(c,"property_id"),"CAMPAIGN",id,action.toUpperCase(Locale.ROOT),"version="+v.version());}
 public Object history(AuthenticatedUser p,Long property,String status,String channel,LocalDate from,LocalDate to,int page,int size){var ids=managementProperties(p,property);page(page,size);String w=" WHERE d.property_id IN (:ids)";var a=new HashMap<String,Object>();a.put("ids",safe(ids));if(status!=null&&!status.isBlank()){w+=" AND d.status=:status";a.put("status",status);}if(channel!=null&&!channel.isBlank()){w+=" AND d.channel=:channel";a.put("channel",channel);}if(from!=null){w+=" AND d.created_at>=:from";a.put("from",from.atStartOfDay());}if(to!=null){w+=" AND d.created_at<:to";a.put("to",to.plusDays(1).atStartOfDay());}if(p.activeRole()==RoleCode.ACCOUNTANT)w+=" AND d.category IN ('INVOICE','PAYMENT')";else if(p.activeRole()==RoleCode.MANAGER)w+=" AND (d.category NOT IN ('INVOICE','PAYMENT') OR EXISTS(SELECT 1 FROM manager_property_capabilities cap WHERE cap.property_id=d.property_id AND cap.manager_id=:actor AND cap.capability='FINANCE_READ'))";a.put("actor",p.id());long total=db.sql("SELECT COUNT(*) FROM communication_deliveries d"+w).params(a).query(Long.class).single();a.put("limit",size);a.put("offset",(long)page*size);var rows=db.sql("SELECT d.id,d.campaign_id,d.property_id,d.recipient_id,u.full_name recipient_name,d.channel,d.category,d.title,d.status,d.attempt_count,d.retryable,d.result_code,d.provider_reference,d.scheduled_at,d.finished_at,n.read_at FROM communication_deliveries d JOIN users u ON u.id=d.recipient_id LEFT JOIN notifications n ON n.id=d.notification_id"+w+" ORDER BY d.id DESC LIMIT :limit OFFSET :offset").params(a).query().listOfRows();var campaigns=db.sql("SELECT id,title,status,scheduled_at,version FROM communication_campaigns WHERE property_id IN (:ids) AND created_by=:actor ORDER BY id DESC LIMIT 50").param("ids",safe(ids)).param("actor",p.id()).query().listOfRows();return Map.of("rows",rows,"campaigns",campaigns,"totalElements",total,"totalPages",(total+size-1)/size,"summary",db.sql("SELECT d.status,COUNT(*) count FROM communication_deliveries d"+w+" GROUP BY d.status").params(a).query().listOfRows());}
 List<Long> managementProperties(AuthenticatedUser p,Long property){if(!Set.of(RoleCode.OWNER,RoleCode.MANAGER,RoleCode.ACCOUNTANT).contains(p.activeRole()))throw denied();var ids=properties(p);if(property!=null){property(p,property);return List.of(property);}return ids;}
 public Object attempts(AuthenticatedUser p,long id){var r=db.sql("SELECT property_id,category FROM communication_deliveries WHERE id=:id").param("id",id).query().singleRow();manage(p,number(r,"property_id"),financeCategory(r.get("category").toString()));return db.sql("SELECT attempt_number,outcome,result_code,provider_reference,attempted_at FROM communication_attempts WHERE delivery_id=:id ORDER BY attempt_number").param("id",id).query().listOfRows();}
 @Transactional public void retry(AuthenticatedUser p,long id){var r=db.sql("SELECT * FROM communication_deliveries WHERE id=:id FOR UPDATE").param("id",id).query().singleRow();manage(p,number(r,"property_id"),financeCategory(r.get("category").toString()));if(!"FAILED".equals(r.get("status"))||!Boolean.TRUE.equals(r.get("retryable"))||number(r,"attempt_count")>=3)throw conflict();db.sql("UPDATE communication_deliveries SET status='QUEUED',next_attempt_at=:now WHERE id=:id").param("now",now()).param("id",id).update();audit(p,number(r,"property_id"),"DELIVERY",id,"RETRY_REQUESTED","Same delivery and business key; bounded attempts");}
 public record Template(@Positive long propertyId,@NotBlank @Size(max=60) String code,@NotBlank @Size(max=180) String name,@NotBlank String eventType,@NotBlank String channel,@NotBlank @Size(max=200) String title,@NotBlank @Size(max=5000) String body,boolean enabled,@Min(0) long version){public Template{eventType=canonicalEvent(eventType);}}
 static final Set<String> VARIABLES=Set.of("name","property","room","code","date","link");
 public static String render(String text,Map<String,?> values){var matcher=java.util.regex.Pattern.compile("\\{\\{([a-zA-Z_]+)}}").matcher(text);StringBuilder out=new StringBuilder();while(matcher.find()){String key=matcher.group(1);if(!VARIABLES.contains(key))throw bad("Biến mẫu không được phép: "+key);matcher.appendReplacement(out,java.util.regex.Matcher.quoteReplacement(Objects.toString(values.get(key),"—")));}matcher.appendTail(out);if(out.toString().contains("{{")||out.toString().contains("}}"))throw bad("Cú pháp biến mẫu không hợp lệ.");return out.toString();}
 public Object templates(AuthenticatedUser p,Long property){return db.sql("SELECT * FROM communication_templates WHERE property_id IN (:ids) ORDER BY id DESC").param("ids",safe(managementProperties(p,property))).query().listOfRows();}
 Map<String,Object> template(AuthenticatedUser p,long id){var row=db.sql("SELECT * FROM communication_templates WHERE id=:id").param("id",id).query().singleRow();manage(p,number(row,"property_id"),false);return row;}
 @Transactional public long saveTemplate(AuthenticatedUser p,Long id,Template t){manage(p,t.propertyId(),false);text(t.title(),200);text(t.body(),5000);if(!CHANNELS.contains(t.channel())||!t.code().matches("[A-Z0-9_-]{1,60}")||!EVENTS.contains(t.eventType())&&!"ANNOUNCEMENT".equals(t.eventType()))throw bad("Mã, sự kiện hoặc kênh mẫu không hợp lệ.");render(t.title(),Map.of());render(t.body(),Map.of());Map<String,Object>a=new HashMap<>();a.put("property",t.propertyId());a.put("code",t.code());a.put("name",t.name());a.put("event",t.eventType());a.put("channel",t.channel());a.put("title",t.title());a.put("body",t.body());a.put("enabled",t.enabled());a.put("actor",p.id());if(id==null)id=insert("INSERT INTO communication_templates(property_id,code,name,event_type,channel,title,body,enabled,updated_by) VALUES(:property,:code,:name,:event,:channel,:title,:body,:enabled,:actor)",a);else{var old=template(p,id);if(number(old,"property_id")!=t.propertyId())throw denied();a.put("id",id);a.put("version",t.version());if(db.sql("UPDATE communication_templates SET code=:code,name=:name,event_type=:event,channel=:channel,title=:title,body=:body,enabled=:enabled,version=version+1,updated_by=:actor,updated_at=CURRENT_TIMESTAMP(6) WHERE id=:id AND version=:version").params(a).update()!=1)throw conflict();}audit(p,t.propertyId(),"TEMPLATE",id,"SAVED","version="+t.version());return id;}
 public record Rule(@Positive long propertyId,@NotBlank String eventType,@NotBlank String audience,@Min(0) @Max(60) int offsetDays,@Min(7) @Max(21) int sendHour,@Min(1) @Max(5) int dailyLimit,boolean enabled,@Min(0) long version){public Rule{eventType=canonicalEvent(eventType);}}
 public Object rules(AuthenticatedUser p,Long property){var ids=managementProperties(p,property);return db.sql("SELECT * FROM communication_rules WHERE property_id IN (:ids)"+(p.activeRole()==RoleCode.ACCOUNTANT?" AND event_type IN ('INVOICE_ISSUED','PAYMENT_OPEN','INVOICE_BEFORE_DUE','INVOICE_DUE','INVOICE_OVERDUE','PAYMENT_CONFIRMED','PAYMENT_FAILED','DEPOSIT_REFUNDED')":"")+" ORDER BY id DESC").param("ids",safe(ids)).query().listOfRows();}
 @Transactional public long saveRule(AuthenticatedUser p,Long id,Rule r){boolean finance=r.eventType().startsWith("INVOICE")||r.eventType().startsWith("PAYMENT")||r.eventType().equals("DEPOSIT_REFUNDED");manage(p,r.propertyId(),finance);if(!EVENTS.contains(r.eventType())||!Set.of("TENANT","STAFF","ASSIGNEE").contains(r.audience())||finance&&!"TENANT".equals(r.audience()))throw bad("Sự kiện/nhóm không hợp lệ. Nhắc tiền chỉ gửi người thuê nguồn.");if(id==null)id=insert("INSERT INTO communication_rules(property_id,event_type,audience,offset_days,send_hour,daily_limit,enabled,created_by) VALUES(:property,:event,:audience,:offset,:hour,:limit,:enabled,:actor)",Map.of("property",r.propertyId(),"event",r.eventType(),"audience",r.audience(),"offset",r.offsetDays(),"hour",r.sendHour(),"limit",r.dailyLimit(),"enabled",r.enabled(),"actor",p.id()));else{var old=db.sql("SELECT * FROM communication_rules WHERE id=:id FOR UPDATE").param("id",id).query().singleRow();if(number(old,"property_id")!=r.propertyId()||!old.get("event_type").equals(r.eventType())||!old.get("audience").equals(r.audience())||number(old,"offset_days")!=r.offsetDays())throw conflict();if(db.sql("UPDATE communication_rules SET send_hour=:hour,daily_limit=:limit,enabled=:enabled,version=version+1,created_by=:actor WHERE id=:id AND version=:version").param("hour",r.sendHour()).param("limit",r.dailyLimit()).param("enabled",r.enabled()).param("actor",p.id()).param("id",id).param("version",r.version()).update()!=1)throw conflict();if(!r.enabled())db.sql("UPDATE communication_deliveries SET status='CANCELLED',result_code='RULE_DISABLED',finished_at=:now WHERE rule_id=:id AND status IN ('QUEUED','SCHEDULED','FAILED')").param("now",now()).param("id",id).update();}audit(p,r.propertyId(),"RULE",id,"SAVED","enabled="+r.enabled());return id;}
 void audit(AuthenticatedUser p,long property,String entity,long id,String action,String description){db.sql("INSERT INTO communication_audit(property_id,actor_id,entity_type,entity_id,action,description) VALUES(:property,:actor,:entity,:id,:action,:description)").param("property",property).param("actor",p.id()).param("entity",entity).param("id",id).param("action",action).param("description",description).update();}
 public record Work(@Positive long propertyId,Long roomId,@NotBlank @Size(max=200) String title,@NotBlank @Size(max=2000) String description,@Positive long assigneeId,@NotNull LocalDateTime startsAt,@NotNull LocalDateTime dueAt,@NotBlank String priority,@NotBlank String status,@NotNull @Size(max=1000) String note,@Min(0) long version,@NotBlank @Size(max=100) String key){public Work{if(startsAt!=null)startsAt=startsAt.truncatedTo(java.time.temporal.ChronoUnit.MICROS);if(dueAt!=null)dueAt=dueAt.truncatedTo(java.time.temporal.ChronoUnit.MICROS);}}
 @Transactional public long saveWork(AuthenticatedUser p,Long id,Work w){property(p,w.propertyId());boolean manager=Set.of(RoleCode.OWNER,RoleCode.MANAGER).contains(p.activeRole());if(manager)manage(p,w.propertyId(),false);else if(id==null)throw denied();text(w.title(),200);text(w.description(),2000);if(w.dueAt().isBefore(w.startsAt())||!Set.of("LOW","NORMAL","HIGH","URGENT").contains(w.priority())||!Set.of("OPEN","IN_PROGRESS","COMPLETED","CANCELLED").contains(w.status()))throw bad("Thời gian hoặc trạng thái công việc không hợp lệ.");if(w.roomId()!=null&&db.sql("SELECT COUNT(*) FROM rooms WHERE id=:room AND property_id=:property").param("room",w.roomId()).param("property",w.propertyId()).query(Long.class).single()!=1)throw denied();if(recipients(w.propertyId()).stream().noneMatch(r->number(r,"id")==w.assigneeId()&&!"TENANT".equals(r.get("recipient_role"))))throw denied();var args=new HashMap<String,Object>();args.put("property",w.propertyId());args.put("room",w.roomId());args.put("title",w.title());args.put("description",w.description());args.put("assignee",w.assigneeId());args.put("start",w.startsAt());args.put("due",w.dueAt());args.put("priority",w.priority());args.put("status",w.status());args.put("note",w.note());args.put("actor",p.id());args.put("key",w.key());if(id==null){db.sql("SELECT id FROM users WHERE id=:id FOR UPDATE").param("id",p.id()).query(Long.class).single();var prior=db.sql("SELECT * FROM operational_tasks WHERE created_by=:actor AND request_key=:key FOR UPDATE").param("actor",p.id()).param("key",w.key()).query().listOfRows();if(!prior.isEmpty()){var old=prior.getFirst();if(number(old,"property_id")!=w.propertyId()||!old.get("title").equals(w.title())||!old.get("description").equals(w.description())||number(old,"assignee_id")!=w.assigneeId()||!CommunicationJobs.datetime(old.get("due_at")).equals(w.dueAt())||!CommunicationJobs.datetime(old.get("starts_at")).equals(w.startsAt())||!Objects.equals(old.get("room_id")==null?null:number(old,"room_id"),w.roomId())||!old.get("note").equals(w.note())||!old.get("priority").equals(w.priority())||!old.get("status").equals(w.status()))throw conflict();return number(old,"id");}id=insert("INSERT INTO operational_tasks(property_id,room_id,title,description,assignee_id,starts_at,due_at,priority,status,note,created_by,request_key) VALUES(:property,:room,:title,:description,:assignee,:start,:due,:priority,:status,:note,:actor,:key)",args);}else{var old=db.sql("SELECT * FROM operational_tasks WHERE id=:id FOR UPDATE").param("id",id).query().singleRow();if(number(old,"property_id")!=w.propertyId())throw denied();if(!manager&&(number(old,"assignee_id")!=p.id()||w.assigneeId()!=p.id()||!old.get("title").equals(w.title())||!old.get("description").equals(w.description())||!CommunicationJobs.datetime(old.get("due_at")).equals(w.dueAt())||!CommunicationJobs.datetime(old.get("starts_at")).equals(w.startsAt())||!Objects.equals(old.get("room_id")==null?null:number(old,"room_id"),w.roomId())||!old.get("priority").equals(w.priority())||"CANCELLED".equals(w.status())))throw denied();args.put("id",id);args.put("version",w.version());if(db.sql("UPDATE operational_tasks SET room_id=:room,title=:title,description=:description,assignee_id=:assignee,starts_at=:start,due_at=:due,priority=:priority,status=:status,note=:note,version=version+1 WHERE id=:id AND version=:version").params(args).update()!=1)throw conflict();}audit(p,w.propertyId(),"TASK",id,"SAVED","status="+w.status()+"; assignee="+w.assigneeId()+"; due="+w.dueAt());long savedVersion=db.sql("SELECT version FROM operational_tasks WHERE id=:id").param("id",id).query(Long.class).single();db.sql("INSERT INTO communication_deliveries(property_id,recipient_id,channel,category,title,body,source_type,source_id,source_key,business_key,status,scheduled_at,next_attempt_at) VALUES(:property,:recipient,'IN_APP','TASK','Công việc vận hành cập nhật',:body,'TASK',:id,:version,:key,'QUEUED',:now,:now)").param("property",w.propertyId()).param("recipient",w.assigneeId()).param("body",w.title()+"; trạng thái "+w.status()+"; hạn "+w.dueAt()+". Mở lịch công việc để xem hồ sơ.").param("id",id).param("version",Long.toString(savedVersion)).param("key",hash("TASK|"+id+"|"+savedVersion+"|"+w.assigneeId())).param("now",now()).update();return id;}
 public Object workHistory(AuthenticatedUser p,long id){var t=db.sql("SELECT * FROM operational_tasks WHERE id=:id").param("id",id).query().singleRow();property(p,number(t,"property_id"));if(!Set.of(RoleCode.OWNER,RoleCode.MANAGER).contains(p.activeRole())&&number(t,"assignee_id")!=p.id())throw denied();return db.sql("SELECT action,description,actor_id,created_at FROM communication_audit WHERE entity_type='TASK' AND entity_id=:id ORDER BY id DESC").param("id",id).query().listOfRows();}
 public Object preferences(AuthenticatedUser p){properties(p);var row=db.sql("SELECT in_app_enabled,email_enabled,category_preferences,quiet_hours_enabled,quiet_hours_start,quiet_hours_end,version FROM notification_preferences WHERE user_id=:id").param("id",p.id()).query().listOfRows();return row.isEmpty()?Map.of("in_app_enabled",true,"email_enabled",false,"quiet_hours_enabled",false,"quiet_hours_start","22:00","quiet_hours_end","07:00","version",0):row.getFirst();}
 public record Preference(boolean quiet,@NotNull LocalTime start,@NotNull LocalTime end,@Min(0) long version){}
 @Transactional public void preferences(AuthenticatedUser p,Preference r){properties(p);db.sql("SELECT id FROM users WHERE id=:id FOR UPDATE").param("id",p.id()).query(Long.class).single();var rows=db.sql("SELECT version FROM notification_preferences WHERE user_id=:id FOR UPDATE").param("id",p.id()).query(Long.class).list();if(!rows.isEmpty()&&rows.getFirst()!=r.version()||rows.isEmpty()&&r.version()!=0)throw conflict();db.sql("INSERT INTO notification_preferences(user_id,quiet_hours_enabled,quiet_hours_start,quiet_hours_end) VALUES(:id,:quiet,:start,:end) ON DUPLICATE KEY UPDATE quiet_hours_enabled=:quiet,quiet_hours_start=:start,quiet_hours_end=:end,version=version+1").param("id",p.id()).param("quiet",r.quiet()).param("start",r.start()).param("end",r.end()).update();}
}
